<?php require_once 'includes/config.php'; require_login(); $pdo=db(); if(!isset($_SESSION['wishlist']))$_SESSION['wishlist']=[]; if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)$_POST['product_id']; if(isset($_SESSION['wishlist'][$id]))unset($_SESSION['wishlist'][$id]);else $_SESSION['wishlist'][$id]=1; flash('success','Wishlist updated.');redirect('wishlist.php');}$items=[];if($_SESSION['wishlist']){$ids=array_keys($_SESSION['wishlist']);$ph=implode(',',array_fill(0,count($ids),'?'));$st=$pdo->prepare("SELECT * FROM products WHERE id IN ($ph)");$st->execute($ids);$items=$st->fetchAll();}$title='Wishlist';require 'includes/header.php'; ?><h1 class="section-title">My Wishlist</h1><div class="row row-cols-2 row-cols-md-4 g-3"><?php foreach($items as $p)require 'includes/product-card.php'; ?></div><?php if(!$items): ?><div class="bg-white border rounded-4 p-5 text-center">Your wishlist is empty. <a href="products.php">Browse products</a>.</div><?php endif; ?><?php require 'includes/footer.php'; ?>
